style.css:
@-moz-document url("https://www.roblox.com/pt/home") {
body {
        background: linear-gradient(45deg, #ff4b5c, #ff9f40, #ffdd63) !important;
        color: white !important;
    }

    .key-container {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        height: 100vh;
    }

    .key {
        width: 100px;
        height: 150px;
        position: relative;
        background: linear-gradient(45deg, #ff4b5c, #ff9f40, #ffdd63);
        border-radius: 20px 20px 10px 10px;
        box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
    }

    .key-head {
        width: 40px;
        height: 20px;
        background-color: #f16e5d;
        border-radius: 10px 10px 0 0;
        position: absolute;
        top: -10px;
        left: 30px;
    }

    .key-body {
        width: 60px;
        height: 100px;
        position: absolute;
        top: 30px;
        left: 20px;
        border-radius: 10px;
        background-image: url('https://www.example.com/sua-imagem.jpg'); /* Substitua pela URL da sua imagem */
        background-size: cover;
        background-position: center;
    }

    .key-tip {
        width: 20px;
        height: 20px;
        background-color: #ffcc00;
        border-radius: 50%;
        position: absolute;
        bottom: -10px;
        left: 40px;
    }

    .key-text {
        margin-top: 20px;
        font-size: 18px;
        color: black !important; /* Texto em preto */
        font-weight: bold;
    }
}
